class Solution {
public:
    vector<vector<int>> findWinners(vector<vector<int>>& matches) {
        map<int, int> losses;
        for (const auto& m : matches) {
            losses.emplace(m[0], 0);
            losses[m[1]]++;
        }
        vector<int> zeroLoss, oneLoss;
        for (const auto& [p, l] : losses) {
            if (l == 0) zeroLoss.push_back(p);
            else if (l == 1) oneLoss.push_back(p);
        }
        return {zeroLoss, oneLoss};
    }
};

class Solution {
    public List<List<Integer>> findWinners(int[][] matches) {
        Map<Integer, Integer> losses = new TreeMap<>();
        for (int[] m : matches) {
            losses.putIfAbsent(m[0], 0);
            losses.put(m[1], losses.getOrDefault(m[1], 0) + 1);
        }
        List<Integer> zeroLoss = new ArrayList<>();
        List<Integer> oneLoss = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : losses.entrySet()) {
            if (e.getValue() == 0) zeroLoss.add(e.getKey());
            else if (e.getValue() == 1) oneLoss.add(e.getKey());
        }
        return Arrays.asList(zeroLoss, oneLoss);
    }
}

/**
 * @param {number[][]} matches
 * @return {number[][]}
 */
var findWinners = function(matches) {
    const losses = new Map();
    for (const [w, l] of matches) {
        if (!losses.has(w)) losses.set(w, 0);
        losses.set(l, (losses.get(l) || 0) + 1);
    }
    const zeroLoss = [];
    const oneLoss = [];
    for (const [p, l] of losses.entries()) {
        if (l === 0) zeroLoss.push(p);
        else if (l === 1) oneLoss.push(p);
    }
    zeroLoss.sort((a, b) => a - b);
    oneLoss.sort((a, b) => a - b);
    return [zeroLoss, oneLoss];
};
